using System.Collections.Generic;
using UnityEngine;

namespace RoguelikePool
{
    /// <summary>
    /// The pool table, set up in the PoolTable prefab (Assets/Prefabs, generated by Tools > Roguelike Pool):
    /// sprite (Visual), cushion colliders (Cushions), 6 pockets (Pockets), rack apex (RackPoint) and cue ball
    /// start (CueBallSpawn). Everything is edited by hand in the prefab; the game reads it all from here.
    /// Portrait orientation: long axis along Y, the player's end (cue ball) at the bottom, the rack at the top.
    /// Scale: 1 world unit = 10 cm.
    ///
    /// At runtime (Awake), the table adds what is not drawn: the cue-only colliders that keep pockets
    /// arcade (<see cref="cueGuardCorner"/> corner jaw extensions, <see cref="sideCueBevel"/> beveled twins
    /// of the long-rail cushions), the safety walls around the play area and the floor/shadow sprites.
    ///
    /// Cushion polygons follow one convention (the generator uses it, keep it when editing points):
    /// points 0 → 1 are the nose (the edge the balls touch), points 2 and 3 the back (point 2 behind point 1).
    /// </summary>
    public class PoolTable : MonoBehaviour
    {
        [Header("Références (prefab)")]
        public SpriteRenderer visual;
        [Tooltip("Bandes : nez = points 0 → 1, dos = points 2 (derrière 1) et 3 (derrière 0).")]
        public PolygonCollider2D[] cushions = new PolygonCollider2D[0];
        [Tooltip("Les 6 poches, ordre TL, TR, ML, MR, BL, BR.")]
        public Pocket[] pockets = new Pocket[0];
        [Tooltip("Apex du triangle.")]
        public Transform rackPoint;
        [Tooltip("Position de départ de la blanche.")]
        public Transform cueBallSpawn;
        [Tooltip("Matériau des bandes (une copie est utilisée en jeu, son rebond suit BallPhysicsSettings).")]
        public PhysicsMaterial2D cushionMaterial;

        [Header("Limites (repère local de la table)")]
        [Tooltip("Tapis : rectangle limité par le nez des bandes.")]
        public Rect playArea = new Rect(-6.35f, -10.8244f, 12.7f, 21.6488f);
        [Tooltip("Partie visible du sprite (cadre en bois et pieds), pour la caméra et l'ombre.")]
        public Rect tableBounds = new Rect(-8.25f, -12.85f, 16.5f, 25.6f);
        [Tooltip("Les murs de sécurité invisibles sont à cette distance autour du tapis.")]
        public float safetyWallMargin = 1.55f;

        [Header("Mâchoires fantômes (blanche uniquement, invisibles)")]
        [Tooltip("Prolongement des bandes vers les poches de coin, le long de la bande, qui ne bloque que la blanche.")]
        public float cueGuardCorner = 0.35f;
        [Tooltip("Biseau du bout des bandes côté poches du milieu, pour la blanche uniquement : la pointe de mâchoire recule de cette distance le long de la bande. 0 = mâchoire droite comme pour les couleurs.")]
        public float sideCueBevel = 0.5f;

        /// <summary>Layer of colliders that only colored balls hit (cushions that have a cue-only twin). Unnamed user layer.</summary>
        public const int ObjectOnlyLayer = 7;

        /// <summary>Runtime copy of <see cref="cushionMaterial"/>, used by every table collider.</summary>
        public PhysicsMaterial2D CushionMaterial
        {
            get
            {
                if (runtimeMaterial == null)
                {
                    runtimeMaterial = cushionMaterial != null
                        ? Instantiate(cushionMaterial)
                        : new PhysicsMaterial2D("Cushion") { friction = 0f, bounceCombine = PhysicsMaterialCombine2D.Multiply, frictionCombine = PhysicsMaterialCombine2D.Multiply };
                    runtimeMaterial.name = "Cushion (runtime)";
                    runtimeMaterial.bounciness = BallPhysicsSettings.Current.cushionBounciness;
                }
                return runtimeMaterial;
            }
        }
        PhysicsMaterial2D runtimeMaterial;

        public IReadOnlyList<Pocket> Pockets => pockets;

        /// <summary>Visible table (frame), local space.</summary>
        public Rect OuterBounds => tableBounds;
        /// <summary>Play area (felt inside the cushion noses), world space.</summary>
        public Rect PlayAreaWorld => new Rect(playArea.position + (Vector2)transform.position, playArea.size);

        /// <summary>Cue ball start.</summary>
        public Vector2 HeadSpot => cueBallSpawn != null ? (Vector2)cueBallSpawn.position : (Vector2)transform.position + new Vector2(0f, -playArea.height / 4f);
        /// <summary>Rack apex.</summary>
        public Vector2 FootSpot => rackPoint != null ? (Vector2)rackPoint.position : (Vector2)transform.position + new Vector2(0f, playArea.height / 4f);

        /// <summary>Side (middle) pockets are the ones near the table's half line.</summary>
        public bool IsSidePocket(Pocket p) => Mathf.Abs(p.transform.localPosition.y - playArea.center.y) < playArea.height / 4f;

        void Awake()
        {
            foreach (var c in GetComponentsInChildren<Collider2D>(true))
                if (!c.isTrigger) c.sharedMaterial = CushionMaterial;
            BallPhysicsSettings.Changed += ApplySettings;
            BuildCueGuards();
            BuildSafetyWalls();
            TableArt.BuildSurroundings(this);
        }

        void OnDestroy()
        {
            BallPhysicsSettings.Changed -= ApplySettings;
            if (runtimeMaterial != null) Destroy(runtimeMaterial);
        }

        /// <summary>Cushion bounciness comes from BallPhysicsSettings (edited live in the Inspector).</summary>
        void ApplySettings()
        {
            float b = BallPhysicsSettings.Current.cushionBounciness;
            if (Mathf.Approximately(CushionMaterial.bounciness, b)) return;
            CushionMaterial.bounciness = b;
            foreach (var c in GetComponentsInChildren<Collider2D>(true))
                if (c.sharedMaterial == CushionMaterial) c.sharedMaterial = CushionMaterial; // re-assign to apply
        }

        // ---------------------------------------------------------------- Runtime colliders

        /// <summary>
        /// Cue-only colliders, under a "CueGuards" child:
        /// - at each cushion end facing a corner pocket, an invisible extension of <see cref="cueGuardCorner"/>
        ///   along the rail (narrows the corner mouth for the cue ball only);
        /// - for each cushion end facing a side pocket, the drawn cushion moves to <see cref="ObjectOnlyLayer"/>
        ///   (colored balls only) and gets a cue-only twin whose nose tip recedes by <see cref="sideCueBevel"/>.
        /// </summary>
        /// <summary>Rebuilds the cue-only colliders after <see cref="cueGuardCorner"/> / <see cref="sideCueBevel"/> changed at runtime.</summary>
        public void RebuildCueGuards()
        {
            var old = transform.Find("CueGuards");
            if (old != null)
            {
                old.gameObject.SetActive(false); // Destroy is deferred: disable the colliders right away
                Destroy(old.gameObject);
            }
            foreach (var cushion in cushions)
            {
                if (cushion == null) continue;
                cushion.gameObject.layer = 0;
                cushion.excludeLayers = 0;
            }
            BuildCueGuards();
        }

        void BuildCueGuards()
        {
            var guards = new GameObject("CueGuards").transform;
            guards.SetParent(transform, false);
            foreach (var cushion in cushions)
            {
                if (cushion == null || cushion.points.Length != 4) continue;
                var p = cushion.points; // cushion-local
                Vector2 rail = (p[1] - p[0]).normalized;
                var twin = (Vector2[])p.Clone();
                bool hasTwin = false;

                for (int end = 0; end < 2; end++)
                {
                    int nose = end == 0 ? 0 : 1, back = end == 0 ? 3 : 2;
                    Vector2 outward = end == 0 ? -rail : rail; // along the rail, toward this end's pocket
                    var pocket = NearestPocket(cushion.transform.TransformPoint(p[nose]));
                    if (pocket == null) continue;

                    if (IsSidePocket(pocket))
                    {
                        float length = Vector2.Distance(p[0], p[1]);
                        float bevel = Mathf.Clamp(sideCueBevel, 0f, length * 0.5f);
                        if (bevel <= 0f) continue;
                        twin[nose] = p[nose] - outward * bevel;
                        hasTwin = true;
                    }
                    else if (cueGuardCorner > 0f)
                    {
                        Vector2 a = p[nose], d = p[back];
                        AddCueGuard(guards, cushion.transform, "CueGuardCorner",
                            new[] { a, a + outward * cueGuardCorner, d + outward * cueGuardCorner, d });
                    }
                }

                if (hasTwin)
                {
                    // Twins instead of an add-on piece: each ball sees one continuous polygon, no seam.
                    cushion.gameObject.layer = ObjectOnlyLayer;
                    cushion.excludeLayers = 1 << Ball.CueLayer;
                    AddCueGuard(guards, cushion.transform, "CueJawSide", twin);
                }
            }
        }

        Pocket NearestPocket(Vector2 world)
        {
            Pocket best = null;
            float bestDist = float.MaxValue;
            foreach (var p in pockets)
            {
                if (p == null) continue;
                float d = Vector2.Distance(world, p.transform.position);
                if (d < bestDist) { best = p; bestDist = d; }
            }
            return best;
        }

        void AddCueGuard(Transform parent, Transform space, string guardName, Vector2[] localPoints)
        {
            var go = new GameObject(guardName);
            go.transform.SetParent(parent, false);
            go.transform.SetPositionAndRotation(space.position, space.rotation);
            go.transform.localScale = space.lossyScale;
            var poly = go.AddComponent<PolygonCollider2D>();
            poly.points = localPoints;
            poly.sharedMaterial = CushionMaterial;
            poly.excludeLayers = ~(1 << Ball.CueLayer); // only the cue ball collides with it
        }

        /// <summary>Solid walls <see cref="safetyWallMargin"/> around the play area: nothing can leave the table.</summary>
        void BuildSafetyWalls()
        {
            var walls = new GameObject("SafetyWalls");
            walls.transform.SetParent(transform, false);
            Rect outer = new Rect(playArea.xMin - safetyWallMargin, playArea.yMin - safetyWallMargin,
                playArea.width + 2f * safetyWallMargin, playArea.height + 2f * safetyWallMargin);
            const float t = 2f;
            AddWall(walls, new Vector2(outer.center.x, outer.yMax + t / 2f), new Vector2(outer.width + 2f * t, t));
            AddWall(walls, new Vector2(outer.center.x, outer.yMin - t / 2f), new Vector2(outer.width + 2f * t, t));
            AddWall(walls, new Vector2(outer.xMin - t / 2f, outer.center.y), new Vector2(t, outer.height + 2f * t));
            AddWall(walls, new Vector2(outer.xMax + t / 2f, outer.center.y), new Vector2(t, outer.height + 2f * t));
        }

        void AddWall(GameObject host, Vector2 center, Vector2 size)
        {
            var box = host.AddComponent<BoxCollider2D>();
            box.offset = center;
            box.size = size;
            box.sharedMaterial = CushionMaterial;
        }

        // ---------------------------------------------------------------- Gizmos (Scene view)

        void OnDrawGizmos()
        {
            Gizmos.matrix = transform.localToWorldMatrix;

            // Play area (felt) in green, visible frame in grey.
            Gizmos.color = new Color(0.3f, 1f, 0.4f, 0.9f);
            DrawRect(playArea);
            Gizmos.color = new Color(1f, 1f, 1f, 0.35f);
            DrawRect(tableBounds);
            Gizmos.color = new Color(1f, 0.3f, 0.3f, 0.35f);
            DrawRect(new Rect(playArea.xMin - safetyWallMargin, playArea.yMin - safetyWallMargin,
                playArea.width + 2f * safetyWallMargin, playArea.height + 2f * safetyWallMargin));

            // Landmarks.
            Gizmos.color = Color.white;
            if (rackPoint != null) DrawCross(transform.InverseTransformPoint(rackPoint.position), 0.4f);
            if (cueBallSpawn != null) DrawCross(transform.InverseTransformPoint(cueBallSpawn.position), 0.4f);

            Gizmos.matrix = Matrix4x4.identity;
            foreach (var p in pockets)
            {
                if (p == null) continue;
                Vector3 c = p.transform.position;
                Gizmos.color = new Color(1f, 0.85f, 0.2f, 1f);
                DrawCircle(c, p.radius);                         // drawn hole
                Gizmos.color = new Color(0.3f, 1f, 0.4f, 0.6f);
                DrawCircle(c, p.ObjectCaptureRadius);            // colored balls fall in
                Gizmos.color = new Color(1f, 1f, 1f, 0.8f);
                DrawCircle(c, p.CueCaptureRadius);               // cue ball falls in
            }
        }

        static void DrawRect(Rect r)
        {
            Vector3 a = new Vector3(r.xMin, r.yMin), b = new Vector3(r.xMax, r.yMin), c = new Vector3(r.xMax, r.yMax), d = new Vector3(r.xMin, r.yMax);
            Gizmos.DrawLine(a, b); Gizmos.DrawLine(b, c); Gizmos.DrawLine(c, d); Gizmos.DrawLine(d, a);
        }

        static void DrawCross(Vector3 c, float s)
        {
            Gizmos.DrawLine(c + new Vector3(-s, 0f), c + new Vector3(s, 0f));
            Gizmos.DrawLine(c + new Vector3(0f, -s), c + new Vector3(0f, s));
        }

        static void DrawCircle(Vector3 c, float r)
        {
            const int n = 48;
            Vector3 prev = c + new Vector3(r, 0f);
            for (int i = 1; i <= n; i++)
            {
                float a = i * Mathf.PI * 2f / n;
                Vector3 next = c + new Vector3(Mathf.Cos(a) * r, Mathf.Sin(a) * r);
                Gizmos.DrawLine(prev, next);
                prev = next;
            }
        }
    }
}
